tool_calls.name:
/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import os, tempfile, time

path = Path('config/config.go')
content = '''package config

import \"fmt\"

type Config struct {
\\tHost       string
\\tListenPort int
}

func DefaultConfig() *Config {
\\treturn &Config{Host: \"localhost\", ListenPort: 8080}
}

func (c *Config) Addr() string {
\\treturn fmt.Sprintf(\"%s:%d\", c.Host, c.ListenPort)
}
'''
fd, temporary = tempfile.mkstemp(dir=path.parent, prefix='.config.go.')
try:
    with os.fdopen(fd, 'w') as f:
        f.write(content)
        f.flush()
        os.fsync(f.fileno())
    os.replace(temporary, path)
    current = time.time()
    os.utime(path, (current, current + 1))
except Exception:
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
    raise
PY
gofmt -w config/config.go
"

